<p><a class="btn ghost" href="/contracts"><?= te('Contracts & signatures') ?></a></p><h1><?= te('Welcome, :name', ['name'=>$worker['full_name']]) ?></h1><p class="sub"><?= te('Your assignments, onboarding tasks, accommodation and travel.') ?></p>
<div class="card"><h2><?= te('Assignments') ?></h2><?php foreach($assignments as $a): ?><p><?= te(':project · :status · :date',['project'=>$a['title'],'status'=>t($a['status']),'date'=>d($a['start_date'])]) ?></p><?php endforeach; ?></div>
<div class="card"><h2><?= te('Onboarding tasks') ?></h2><p class="muted"><?= te('Do not enter Social Security numbers, banking details or identity documents here.') ?></p><?php foreach($tasks as $t): ?><form method="post" class="card"><?= csrf_field() ?><input type="hidden" name="task_id" value="<?= (int)$t['id'] ?>"><h2><?= e($t['project'].' · '.$t['title']) ?></h2><p><?= e($t['instructions']) ?></p><span class="tag"><?= e($t['status']) ?></span><?php if(in_array($t['status'],['pending','rejected'],true)): ?><label><?= te('Completion note') ?></label><textarea name="response" maxlength="2000" required></textarea><button class="btn"><?= te('Submit for review') ?></button><?php endif; ?></form><?php endforeach; ?></div>
<div class="grid g2"><div class="card"><h2><?= te('Your accommodation') ?></h2><?php foreach($lodging as $l): ?><p><?= te(':hotel · room :room · :start to :end',['hotel'=>$l['name'],'room'=>$l['room_number'],'start'=>d($l['check_in']),'end'=>d($l['check_out'])]) ?></p><?php endforeach; ?></div><div class="card"><h2><?= te('Your travel') ?></h2><?php foreach($travel as $t): ?><p><?= e($t['carrier'].' · '.$t['depart_from'].' → '.$t['arrive_at'].' · '.$t['depart_time']) ?></p><?php endforeach; ?></div></div>
<div class="card"><h2><?= te('Your work assignment') ?></h2><?php foreach($details as $d): ?><p><?= te(':project · :trade · :shift · supervisor :name',['project'=>$d['title'],'trade'=>$d['trade'],'shift'=>$d['shift_label'],'name'=>$d['supervisor']]) ?></p><?php endforeach; ?></div><div class="card"><h2><?= te('Your pickups') ?></h2><?php foreach($routes as $r): ?><p><?= te(':date :time · :stop · driver :name',['date'=>d($r['runs_on']),'time'=>$r['depart_time'],'stop'=>$r['pickup_stop'],'name'=>$r['driver']]) ?></p><?php endforeach; ?></div><div class="card"><h2><?= te('Your applications') ?></h2><?php foreach($applications as $a): ?><div class="card"><h2><?= e($a['title'].' · '.$a['project']) ?></h2><p><?= e($a['stage']) ?></p><?php if($a['stage']==='offered'&&!$a['has_contract']&&!$a['contract_required']): ?><div><?= nl2br(e($a['offer_text'])) ?></div><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="accept_offer"><input type="hidden" name="application_id" value="<?= (int)$a['id'] ?>"><label><input style="width:auto" type="checkbox" name="consent" required> <?= te('I accept the offer terms displayed above and intend to sign electronically.') ?></label><label><?= te('Your full name') ?></label><input name="signer_name" required maxlength="190"><button class="btn"><?= te('Sign and accept offer') ?></button></form><?php endif; ?></div><?php endforeach; ?></div>